mapper.select:
SELECT ir.id as interviewRecordId, c.id as candidateId, c.real_name as realName, c.identity_num as identityNum, c.mobile as mobile, c.sex as sex, c.email as email, c.job_id as jobId, ir.create_time as createTime, ir.result as result, ir.answer_content as answerContent, ir.take_time as takeTime, ir.totalscore as totalscore, ir.offer_status as offsta, ir.analysis as analysis, j.job_name as jobName, j.image as qrcodeUrl, ir.interviewresult as interviewresult FROM interview_record ir LEFT JOIN candidate c ON c.id = ir.candidate_id LEFT JOIN job j ON c.job_id = j.id WHERE 1 = 1
AND c.real_name LIKE concat('%', #{paramMap.realName},'%')
AND c.mobile LIKE concat('%', #{paramMap.mobile},'%')
AND ir.job_id = #{paramMap.jobId}
AND c.id = #{paramMap.candidateId}
ORDER BY ir.create_time DESC

